// Server Security Monitor v3.0
(()=>{'use strict';
 const $=id=>document.getElementById(id),grid=$('gamesInstallCards');if(!grid)return;
 let snapshot=null,request=null,review=null,jobId='',operation='',poller=null,loading=false,credentialTimer=null;
 const el=(tag,text,cls)=>{const n=document.createElement(tag);if(text!==undefined)n.textContent=text;if(cls)n.className=cls;return n;};
 const can=()=>window.PanelAccess?.can('games-install')===true;
 const card=el('article',undefined,'panel catalog-card');card.id='zoneInstallCard';
 const heading=el('div',undefined,'catalog-card-heading'),logo=el('img');logo.src='/game-logo-samp.png';logo.alt='SA-MP';logo.className='catalog-logo';heading.append(logo,el('h3','SA-MP GM Zone'));
 const stateLine=el('p','Consultando…','catalog-state'),button=el('button','Instalar GM Zone','primary-button');button.type='button';button.disabled=true;
 const credentials=el('button','Acceso al administrador del foro','secondary-button');credentials.type='button';credentials.hidden=true;
 card.append(heading,el('span','Juego + web + base de datos','panel-tag'),el('p','Configura y compila la GM, prepara su web, MySQL, phpMyAdmin y una cuenta FTPS.'),stateLine,button,credentials);
 function attach(){if(!grid.contains(card))grid.append(card);}
 new MutationObserver(attach).observe(grid,{childList:true});attach();
 const dialog=el('dialog');dialog.id='zoneDialog';dialog.className='port-dialog games-dialog';dialog.setAttribute('aria-labelledby','zoneTitle');
 dialog.innerHTML=`<div class="dialog-surface games-dialog-surface"><h2 id="zoneTitle">Instalar SA-MP GM Zone</h2><p id="zoneMessage" role="status"></p><form id="zoneForm" class="games-settings">
 <label>Nombre del servidor (Zone Roleplay se agrega al final)<input id="zoneName" pattern="[A-Za-z]{1,24}" maxlength="24" placeholder="Ejemplo: Copia" autocomplete="off" required></label><p id="zoneNamePreview" class="games-note"></p>
 <label>Dominio de la web<input id="zoneDomain" maxlength="253" placeholder="rol.ejemplo.com" autocomplete="url" required></label><p class="games-note">Sin http://, https://, puerto ni ruta. Se mostrará en la GM. El dominio y su DNS se configuran por separado.</p>
 <div class="games-field-pair"><label>Puerto UDP<input id="zonePort" type="number" min="1024" max="65535" value="7777" required></label><label>Jugadores máximos<input id="zonePlayers" type="number" min="1" max="500" value="50" required></label></div>
 <div class="games-field-pair"><label>Nombre de la base<input id="zoneDatabase" value="zone_rp" pattern="[a-z][a-z0-9_]{2,47}" maxlength="48" required autocomplete="off"></label><label>Usuario MySQL<input id="zoneDbUser" value="zone_user" pattern="[a-z][a-z0-9_]{2,23}" maxlength="24" required autocomplete="off"></label></div>
 <label>Contraseña MySQL<input id="zoneDbPassword" type="password" minlength="16" maxlength="64" autocomplete="new-password" required></label>
 <label>Contraseña RCON<input id="zoneRcon" type="password" minlength="16" maxlength="64" autocomplete="new-password" required></label>
 <div class="games-field-pair"><button id="zoneGenerate" type="button" class="secondary-button">Generar contraseñas</button><label class="games-check"><input id="zoneShowPasswords" type="checkbox">Mostrar contraseñas</label></div>
 <label>Usuario FTP<input id="zoneFtp" value="zoneftp" pattern="[a-z][a-z0-9_\\-]{2,31}" minlength="3" maxlength="32" autocomplete="off" required></label>
 <p class="games-note">MySQL y RCON usan las contraseñas indicadas arriba. Guardalas antes de continuar. La contraseña FTP se genera y guarda cifrada; podrás consultarla en Gestionar juegos con Windows Hello. Instalar no solicita Windows Hello.</p>
 <p class="games-note">Web en http://IP/ y phpMyAdmin en http://IP/phpmyadmin/. MySQL queda local. Foro SMF en /foro/ con registro web deshabilitado; las cuentas se crean desde el juego. El correo no se configura. Esta opción comparte el espacio de SA-MP: permite una instalación de juego a la vez.</p>
 </form><form id="zoneDomainSettings" class="games-settings" hidden><label>Dominio de la web<input id="zoneRepairDomain" maxlength="253" placeholder="rol.ejemplo.com" autocomplete="url" required></label><p class="games-note">Ingresá el dominio que debe mostrar la GM, sin protocolo, puerto ni ruta. No se crean registros DNS automáticamente.</p></form><dl id="zoneDetails" hidden></dl><div class="dialog-actions"><button id="zoneClose" type="button" class="secondary-button">Cerrar</button><button id="zoneReview" type="button" class="primary-button">Revisar instalación</button><button id="zoneApply" type="button" class="primary-button" hidden>Confirmar instalación</button></div></div>`;
 document.body.append(dialog);
 function message(text,error=false){$('zoneMessage').textContent=text;$('zoneMessage').classList.toggle('games-warning',error);}
 function randomPassword(){const data=crypto.getRandomValues(new Uint8Array(32));return Array.from(data,v=>'ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789_-'[v%64]).join('');}
 function generate(){$('zoneDbPassword').value=randomPassword();$('zoneRcon').value=randomPassword();}
 function checkDomain(id){const input=$(id),value=input.value.toLowerCase(),labels=value.split('.'),last=labels.at(-1),valid=value.length>=1&&value.length<=253&&/^[a-z0-9.-]+$/.test(value)&&labels.length>=2&&labels.every(label=>label.length<=63&&/^[a-z0-9](?:[a-z0-9-]*[a-z0-9])?$/.test(label))&&(/^[a-z]{2,63}$/.test(last)||/^xn--[a-z0-9-]+$/.test(last));input.setCustomValidity(valid?'':'Ingresá un dominio válido, sin protocolo, IP, puerto ni ruta.');if(valid)input.value=value;return valid;}
 for(const id of ['zoneDomain','zoneRepairDomain'])$(id).addEventListener('input',()=>$(id).setCustomValidity(''));
 async function json(path,options){const response=await fetch('/api/games/zone'+path,{...options,signal:AbortSignal.timeout((path===''||path==='/forum-credentials')?110000:15000)});const data=await response.json();if(data.action_token)state.actionToken=data.action_token;if(!response.ok)throw new Error(data.error||'No se pudo consultar Zone.');return data;}
 function render(){const zone=snapshot?.installed&&snapshot.edition==='zone';stateLine.textContent=zone?'GM Zone instalada'+(snapshot.forum_installed?' · Foro SMF instalado':' · Foro pendiente'):snapshot?.installed?'SA-MP clásico instalado':snapshot?'No instalado'+(!snapshot.compatible?' · '+(snapshot.notice||'Distribución no verificada.'):''):'Consultando…';button.textContent=zone?'Actualizar GM y web':'Instalar GM Zone';button.disabled=!can()||!snapshot||snapshot.conflict||!snapshot.compatible||(snapshot.installed&&(!zone||!snapshot.maintenance_revision));credentials.hidden=!zone||!snapshot.forum_installed;credentials.disabled=!can();}
 async function load(){if(loading)return;loading=true;try{snapshot=await json('');render();}catch(error){stateLine.textContent=error.message;}finally{loading=false;}}
 function busy(value){$('zoneReview').disabled=value;$('zoneApply').disabled=value;}
 function showReview(plan){review=plan;$('zoneForm').hidden=true;$('zoneDomainSettings').hidden=true;$('zoneReview').hidden=true;$('zoneApply').hidden=false;$('zoneDetails').hidden=false;const details=$('zoneDetails');details.replaceChildren();for(const [label,value] of [['Servidor',plan.settings.hostname],['Dominio de la web',request.web_domain],['Sistema',plan.distribution],['Juego',plan.directory],['Web',plan.web_directory],['Puerto',plan.settings.port+'/UDP'],['Base',request.database],['Usuario MySQL',request.db_user],['FTP',request.ftp_user],['Dependencias',plan.packages.join(', ')],['Aviso',plan.warning]])details.append(el('dt',label),el('dd',value));message('Revisá los datos antes de confirmar.');busy(false);}
 async function poll(){if(!dialog.open)return;try{const data=await json('');if(data.job.id!==jobId)throw new Error('La operación cambió. Volvé a revisarla.');if(data.job.status==='running'){message(data.job.message);poller=setTimeout(poll,2000);return;}if(data.job.status==='error'){message(data.job.message,true);if(operation==='repair'){busy(false);return;}$('zoneReview').hidden=false;$('zoneForm').hidden=false;$('zoneApply').hidden=true;review=null;busy(false);return;}if(operation==='plan')showReview(data.job.plan);else{message(data.job.message);$('zoneApply').hidden=true;request=null;review=null;for(const id of ['zoneDbPassword','zoneRcon'])$(id).value='';snapshot=null;setTimeout(load,5000);}}catch(error){message(error.message,true);busy(false);}}
 async function start(kind,body){operation=kind;busy(true);message('Esperando al servidor…');try{const data=await json('/'+kind,{method:'POST',headers:{'Content-Type':'application/json','X-StoryPulse-Token':state.actionToken},body:JSON.stringify(body)});jobId=data.job.id;poller=setTimeout(poll,1000);}catch(error){message(error.message,true);busy(false);}}
 button.addEventListener('click',()=>{if(!can())return;request=null;review=null;
 if(snapshot?.installed&&snapshot.edition==='zone'){
  review={repair:true,revision:snapshot.maintenance_revision};$('zoneTitle').textContent='Actualizar GM y web';$('zoneForm').hidden=true;$('zoneDomainSettings').hidden=false;$('zoneRepairDomain').value=snapshot.details?.web_domain||'';$('zoneRepairDomain').setCustomValidity('');$('zoneReview').hidden=true;$('zoneDetails').hidden=true;$('zoneApply').hidden=false;$('zoneApply').textContent='Confirmar actualización';message('El dominio se aplicará a los textos de la GM antes de compilarla. Se comprobarán la web y el registro, y se conservarán cuentas y datos. Salí del juego antes de confirmar; el servidor debe estar sin jugadores.');busy(false);dialog.showModal();return;
 }
 $('zoneTitle').textContent='Instalar SA-MP GM Zone';$('zoneDomainSettings').hidden=true;$('zoneApply').textContent='Confirmar instalación';generate();$('zoneForm').hidden=false;$('zoneReview').hidden=false;$('zoneApply').hidden=true;$('zoneDetails').hidden=true;$('zoneShowPasswords').checked=false;for(const id of ['zoneDbPassword','zoneRcon'])$(id).type='password';message('');busy(false);dialog.showModal();});
 $('zoneName').addEventListener('input',()=>{$('zoneNamePreview').textContent=$('zoneName').value?$('zoneName').value+' Zone Roleplay':'';});
 $('zoneGenerate').addEventListener('click',generate);$('zoneShowPasswords').addEventListener('change',()=>{for(const id of ['zoneDbPassword','zoneRcon'])$(id).type=$('zoneShowPasswords').checked?'text':'password';});
 $('zoneReview').addEventListener('click',()=>{checkDomain('zoneDomain');if(!$('zoneForm').reportValidity())return;request={name:$('zoneName').value,web_domain:$('zoneDomain').value,port:Number($('zonePort').value),maxplayers:Number($('zonePlayers').value),database:$('zoneDatabase').value,db_user:$('zoneDbUser').value,db_password:$('zoneDbPassword').value,rcon_password:$('zoneRcon').value,ftp_user:$('zoneFtp').value};void start('plan',request);});
 $('zoneForm').addEventListener('submit',event=>{event.preventDefault();$('zoneReview').click();});
 $('zoneDomainSettings').addEventListener('submit',event=>{event.preventDefault();$('zoneApply').click();});
 $('zoneApply').addEventListener('click',()=>{if(review?.repair){checkDomain('zoneRepairDomain');if(!$('zoneDomainSettings').reportValidity())return;void start('repair',{confirm:true,revision:review.revision,web_domain:$('zoneRepairDomain').value});return;}if(review&&request)void start('apply',{...request,revision:review.revision,confirm:true});});
 credentials.addEventListener('click',async()=>{if(!can())return;clearTimeout(credentialTimer);$('zoneTitle').textContent='Acceso al administrador del foro';$('zoneForm').hidden=true;$('zoneDomainSettings').hidden=true;$('zoneReview').hidden=true;$('zoneApply').hidden=true;$('zoneDetails').hidden=true;message('Confirmá Windows Hello para consultar el acceso.');dialog.showModal();try{const row=await json('/forum-credentials',{method:'POST',headers:{'Content-Type':'application/json','X-StoryPulse-Token':state.actionToken},body:'{}'});message('Foro: '+row.url+' · Usuario: '+row.username+' · Contraseña: '+row.password);credentialTimer=setTimeout(()=>message('Acceso ocultado.'),row.hide_after_ms||30000);}catch(error){message(error.message,true);}});
 $('zoneClose').addEventListener('click',()=>dialog.close());dialog.addEventListener('close',()=>{clearTimeout(poller);clearTimeout(credentialTimer);message('');request=null;review=null;$('zoneDomainSettings').hidden=true;for(const id of ['zoneDbPassword','zoneRcon','zoneDomain','zoneRepairDomain']){$(id).value='';$(id).setCustomValidity('');}});
 window.addEventListener('storypulse-view',event=>{if(event.detail==='games-install')void load();});
 if(state.view==='games-install')void load();
})();
